#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>
#include <algorithm>  // for std::max

#include "Halide.h"

// include common definitions (DATA_TYPE, NX, NY, TMAX, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (if any)
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize input arrays, translated from the original C init_array().
 *
 * C prototype:
 *   void init_array (int tmax, int nx, int ny,
 *                    DATA_TYPE ex[nx][ny],
 *                    DATA_TYPE ey[nx][ny],
 *                    DATA_TYPE hz[nx][ny],
 *                    DATA_TYPE _fict_[tmax])
 *
 * In Halide, we represent:
 *   ex,ey,hz as Buffer<num_t, 2> with shape (ny, nx) and access ex(j, i)
 *   _fict_   as Buffer<num_t, 1> with shape (tmax)
 */
static void init_array(int tmax,
                       int nx,
                       int ny,
                       Halide::Buffer<num_t, 2> ex,
                       Halide::Buffer<num_t, 2> ey,
                       Halide::Buffer<num_t, 2> hz,
                       Halide::Buffer<num_t, 1> fict) {
    Var i("i"), j("j"), t("t");

    Func init_ex("init_ex"), init_ey("init_ey"), init_hz("init_hz"), init_fict("init_fict");

    // _fict_[i] = (DATA_TYPE) i;
    init_fict(t) = cast<num_t>(t);

    // ex[i][j] = (i * (j+1)) / nx;
    // ey[i][j] = (i * (j+2)) / ny;
    // hz[i][j] = (i * (j+3)) / nx;
    //
    // Remember: Buffer is indexed as (j, i) == C's [i][j].
    init_ex(j, i) = cast<num_t>(i * (j + 1)) / cast<int>(nx);
    init_ey(j, i) = cast<num_t>(i * (j + 2)) / cast<int>(ny);
    init_hz(j, i) = cast<num_t>(i * (j + 3)) / cast<int>(nx);

    // A simple but reasonably efficient schedule for initialization:
    constexpr int vec_bytes   = 32;                           // target ~256-bit vectors
    constexpr int vec_width   = std::max(1, vec_bytes / (int)sizeof(num_t));
    const int     tile_x_init = vec_width * 16;
    const int     tile_y_init = 16;

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    // Vectorize and parallelize the time initialization.
    init_fict
        .compute_root()
        .vectorize(t, vec_width);

    // Initialize ex/ey/hz in tiles, parallel in the outer y dimension, vectorized in x.
    init_ex
        .compute_root()
        .tile(j, i, xo, yo, xi, yi, tile_x_init, tile_y_init)
        .parallel(yo)
        .vectorize(xi, vec_width);
    init_ey
        .compute_root()
        .tile(j, i, xo, yo, xi, yi, tile_x_init, tile_y_init)
        .parallel(yo)
        .vectorize(xi, vec_width);
    init_hz
        .compute_root()
        .tile(j, i, xo, yo, xi, yi, tile_x_init, tile_y_init)
        .parallel(yo)
        .vectorize(xi, vec_width);

    // Realize into the provided Buffers.
    init_fict.realize(fict);
    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem sizes from PolyBench
    int tmax = TMAX;
    int nx   = NX;
    int ny   = NY;

    // Buffers for ex, ey, hz.
    //
    // C layout: ex[nx][ny] with ex[i][j]
    // Halide layout: (ny, nx) so that ex(j, i) corresponds to ex[i][j].
    Halide::Buffer<num_t, 2> exA(ny, nx);
    Halide::Buffer<num_t, 2> eyA(ny, nx);
    Halide::Buffer<num_t, 2> hzA(ny, nx);

    // Second set of buffers for double-buffering in time.
    Halide::Buffer<num_t, 2> exB(ny, nx);
    Halide::Buffer<num_t, 2> eyB(ny, nx);
    Halide::Buffer<num_t, 2> hzB(ny, nx);

    // _fict_[t] array
    Halide::Buffer<num_t, 1> fict(tmax);

    // Initialize arrays
    init_array(tmax, nx, ny, exA, eyA, hzA, fict);

    // Build the Halide pipeline that performs a single time-step.
    //
    // Inputs for the pipeline (current time-step fields)
    ImageParam ex_param(type_of<num_t>(), 2, "ex_param");
    ImageParam ey_param(type_of<num_t>(), 2, "ey_param");
    ImageParam hz_param(type_of<num_t>(), 2, "hz_param");

    // Scalar parameter for _fict_[t] at the current time-step.
    Param<num_t> fict_param("fict_param");

    // Vars: j is the fast (x/column), i is the slow (y/row).
    Var j("j"), i("i");

    // Constants SCALAR_VAL(0.5) and SCALAR_VAL(0.7), in the correct numeric type.
    Expr half         = cast<num_t>(Expr(0.5));
    Expr seven_tenths = cast<num_t>(Expr(0.7));

    // New fields after a single time step.
    Func ey1("ey1"), ex1("ex1"), hz1("hz1");

    // To safely express the finite-difference stencils without any
    // out-of-bounds accesses (even in dead branches of select()),
    // wrap hz_param in a repeat_edge boundary condition. This lets us
    // reference hz at i-1 / j-1 everywhere, and still have Halide's
    // bounds inference succeed.
    Func hz_clamped = BoundaryConditions::repeat_edge(hz_param);

    // --------------------------------------------------------------------
    // ey-update:
    //
    // C code:
    //   for (j = 0; j < ny; j++)
    //     ey[0][j] = _fict_[t];
    //
    //   for (i = 1; i < nx; i++)
    //     for (j = 0; j < ny; j++)
    //       ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    // Halide layout: ey1(j, i) corresponds to ey[i][j].
    // We fuse the two loops into a single pure definition:
    //   if i == 0:
    //       ey1(j,0) = fict_param;
    //   else:
    //       ey1(j,i) = ey_param(j,i) - 0.5*(hz_param(j,i) - hz_param(j, i-1));
    //
    // The use of hz_clamped ensures hz_clamped(j, i-1) is always valid,
    // even for i == 0, though the branch selects fict_param in that case.
    // --------------------------------------------------------------------
    ey1(j, i) = select(i == 0,
                       fict_param,
                       ey_param(j, i) -
                           half * (hz_clamped(j, i) - hz_clamped(j, i - 1)));

    // --------------------------------------------------------------------
    // ex-update:
    //
    // C code:
    //   for (i = 0; i < nx; i++)
    //     for (j = 1; j < ny; j++)
    //       ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    // Halide layout: ex1(j, i) corresponds to ex[i][j].
    // Fused into a single pure definition:
    //   if j == 0:
    //       ex1(0,i) = ex_param(0,i);    // unchanged
    //   else:
    //       ex1(j,i) = ex_param(j,i) - 0.5*(hz(j,i) - hz(j-1,i));
    //
    // Again hz_clamped avoids any out-of-bounds for j-1.
    // --------------------------------------------------------------------
    ex1(j, i) = select(j == 0,
                       ex_param(j, i),
                       ex_param(j, i) -
                           half * (hz_clamped(j, i) - hz_clamped(j - 1, i)));

    // --------------------------------------------------------------------
    // hz-update:
    //
    // C code:
    //   for (i = 0; i < nx - 1; i++)
    //     for (j = 0; j < ny - 1; j++)
    //       hz[i][j] = hz[i][j]
    //                  - 0.7 * (ex[i][j+1] - ex[i][j]
    //                          + ey[i+1][j] - ey[i][j]);
    //
    // Halide layout: hz1(j, i) corresponds to hz[i][j].
    //
    // We follow the original semantics exactly:
    //   * Initialize hz1(j,i) with the old value hz_param(j,i).
    //   * Over the interior region i in [0..nx-2], j in [0..ny-2],
    //     apply the update that uses the NEW ex1 and ey1.
    //
    // Express this as a pure definition plus a single update step.
    // --------------------------------------------------------------------
    hz1(j, i) = hz_param(j, i);

    // RDom over the interior region: j in [0..ny-2], i in [0..nx-2].
    RDom r_hz(0, hz_param.dim(0).extent() - 1,   // j: 0 .. ny-2
              0, hz_param.dim(1).extent() - 1,   // i: 0 .. nx-2
              "r_hz");

    hz1(r_hz.x, r_hz.y) =
        hz1(r_hz.x, r_hz.y) -
        seven_tenths *
            ((ex1(r_hz.x + 1, r_hz.y) - ex1(r_hz.x, r_hz.y)) +
             (ey1(r_hz.x, r_hz.y + 1) - ey1(r_hz.x, r_hz.y)));

    // --------------------------------------------------------------------
    // Scheduling
    //
    // We target a modern x64 CPU with 32 cores. We:
    //   * Vectorize across the fast j-dimension.
    //   * Parallelize across the slow i-dimension.
    //   * For hz1, also vectorize and parallelize the update step
    //     over its reduction domain.
    //
    // We choose a nominal 32-byte vector width (i.e. AVX2) and
    // derive the element count from sizeof(num_t).
    // --------------------------------------------------------------------
    constexpr int vec_bytes = 32; // 256-bit vectors
    const int vec_width = std::max(1, vec_bytes / (int)sizeof(num_t));

    // ex1 and ey1 are simple pointwise stencils off ex/ey and hz;
    // compute them fully, parallel over rows, vectorized over columns.
    ex1
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    ey1
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // hz1 has a pure initialization and one update step.
    hz1.compute_root();
    // Pure step: copy old hz; parallel over rows, vector over cols.
    hz1
        .parallel(i)
        .vectorize(j, vec_width);
    // Update step: finite-difference over interior using ex1/ey1.
    hz1.update()
        .parallel(r_hz.y)
        .vectorize(r_hz.x, vec_width);

    // Build a Pipeline with three outputs: ex1, ey1, hz1.
    Pipeline fdtd_step({ex1, ey1, hz1});

    // JIT-compile once; we'll re-use it for every time-step.
    fdtd_step.compile_jit();

    // Double-buffering pointers for time-stepping.
    Halide::Buffer<num_t, 2> *ex_curr = &exA;
    Halide::Buffer<num_t, 2> *ey_curr = &eyA;
    Halide::Buffer<num_t, 2> *hz_curr = &hzA;

    Halide::Buffer<num_t, 2> *ex_next = &exB;
    Halide::Buffer<num_t, 2> *ey_next = &eyB;
    Halide::Buffer<num_t, 2> *hz_next = &hzB;

    // Start timing.
    auto start = std::chrono::high_resolution_clock::now();

    // Time-stepping loop (host-driven).
    for (int t = 0; t < tmax; t++) {
        // Bind current input fields.
        ex_param.set(*ex_curr);
        ey_param.set(*ey_curr);
        hz_param.set(*hz_curr);

        // Set current _fict_[t] value.
        fict_param.set(fict(t));

        // Realize next time-step into ex_next, ey_next, hz_next.
        Realization r({*ex_next, *ey_next, *hz_next});
        fdtd_step.realize(r);

        // Swap current and next buffers for the next iteration.
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    // Stop timing.
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Final fields are in *ex_curr, *ey_curr, *hz_curr.
    Halide::Buffer<num_t, 2> &ex_final = *ex_curr;
    Halide::Buffer<num_t, 2> &ey_final = *ey_curr;
    Halide::Buffer<num_t, 2> &hz_final = *hz_curr;

    // Optional: print the arrays to prevent dead-code elimination
    // (and to roughly match the original PolyBench behavior).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print ex
        for (int ii = 0; ii < nx; ii++) {
            for (int jj = 0; jj < ny; jj++) {
                std::cerr << ex_final(jj, ii) << '\n';
            }
        }

        // Print ey
        for (int ii = 0; ii < nx; ii++) {
            for (int jj = 0; jj < ny; jj++) {
                std::cerr << ey_final(jj, ii) << '\n';
            }
        }

        // Print hz
        for (int ii = 0; ii < nx; ii++) {
            for (int jj = 0; jj < ny; jj++) {
                std::cerr << hz_final(jj, ii) << '\n';
            }
        }
    }

    // Print elapsed time in seconds (as in gemm.cpp example).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
