#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize input arrays, translated from the original C init_array().
 *
 * C prototype:
 *   void init_array (int tmax, int nx, int ny,
 *                    DATA_TYPE ex[nx][ny],
 *                    DATA_TYPE ey[nx][ny],
 *                    DATA_TYPE hz[nx][ny],
 *                    DATA_TYPE _fict_[tmax])
 *
 * In Halide, we represent:
 *   ex,ey,hz as Buffer<num_t, 2> with shape (ny, nx) and access ex(j, i)
 *   _fict_   as Buffer<num_t, 1> with shape (tmax)
 */
static void init_array(int tmax,
                       int nx,
                       int ny,
                       Halide::Buffer<num_t, 2> ex,
                       Halide::Buffer<num_t, 2> ey,
                       Halide::Buffer<num_t, 2> hz,
                       Halide::Buffer<num_t, 1> fict) {
    Var i("i"), j("j"), t("t");

    Func init_ex("init_ex"), init_ey("init_ey"), init_hz("init_hz"), init_fict("init_fict");

    // Scalar constants as Expr in the correct type.
    Expr nx_f = cast<num_t>(nx);
    Expr ny_f = cast<num_t>(ny);

    // _fict_[t] = (DATA_TYPE) t;
    init_fict(t) = cast<num_t>(t);

    // ex[i][j] = (i * (j+1)) / nx;
    // ey[i][j] = (i * (j+2)) / ny;
    // hz[i][j] = (i * (j+3)) / nx;
    //
    // Remember: Buffer is indexed as (j, i) == C's [i][j].
    init_ex(j, i) = cast<num_t>(i * (j + 1)) / nx_f;
    init_ey(j, i) = cast<num_t>(i * (j + 2)) / ny_f;
    init_hz(j, i) = cast<num_t>(i * (j + 3)) / nx_f;

    // Simple CPU schedule: compute at root, parallelize over rows (i),
    // vectorize over the contiguous dimension (j).
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    init_fict.compute_root()
             .vectorize(t, vec_width);

    init_ex.compute_root()
           .parallel(i)
           .vectorize(j, vec_width);

    init_ey.compute_root()
           .parallel(i)
           .vectorize(j, vec_width);

    init_hz.compute_root()
           .parallel(i)
           .vectorize(j, vec_width);

    // Realize into the provided Buffers.
    init_fict.realize(fict);
    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem sizes from PolyBench
    int tmax = TMAX;
    int nx   = NX;
    int ny   = NY;

    // Buffers for ex, ey, hz.
    //
    // C layout: ex[nx][ny] with ex[i][j]
    // Halide layout: (ny, nx) so that ex(j, i) corresponds to ex[i][j].
    Halide::Buffer<num_t, 2> exA(ny, nx);
    Halide::Buffer<num_t, 2> eyA(ny, nx);
    Halide::Buffer<num_t, 2> hzA(ny, nx);

    // Second set of buffers for double-buffering in time.
    Halide::Buffer<num_t, 2> exB(ny, nx);
    Halide::Buffer<num_t, 2> eyB(ny, nx);
    Halide::Buffer<num_t, 2> hzB(ny, nx);

    // _fict_[t] array
    Halide::Buffer<num_t, 1> fict(tmax);

    // Initialize arrays
    init_array(tmax, nx, ny, exA, eyA, hzA, fict);

    // Build the Halide pipeline that performs a single time-step.
    //
    // Inputs for the pipeline (current time-step fields)
    ImageParam ex_param(type_of<num_t>(), 2, "ex_param");
    ImageParam ey_param(type_of<num_t>(), 2, "ey_param");
    ImageParam hz_param(type_of<num_t>(), 2, "hz_param");

    // Scalar parameter for _fict_[t] at the current time-step.
    Param<num_t> fict_param("fict_param");

    // Vars: j is the fast (x/column), i is the slow (y/row).
    Var j("j"), i("i");

    // Numeric constants in the appropriate type.
    Expr half         = cast<num_t>(0.5);
    Expr seven_tenths = cast<num_t>(0.7);

    // New fields after a single time step.
    Func ey1("ey1"), ex1("ex1"), hz1("hz1");

    // We rewrite the time-step updates as *pure* Funcs (no update
    // definitions) to enable straightforward vectorization and
    // parallelization.
    //
    // To safely handle neighbor accesses near array edges, we wrap
    // hz, ex, and ey in repeat_edge() boundary-condition Funcs.
    // This tells Halide that out-of-bounds accesses are clamped
    // to the edge, so bounds inference succeeds even when indices
    // like (j-1) or (i+1) appear inside expressions.
    //
    // Semantically, we still reproduce the original C code:
    //   - ex and ey interior points are updated using hz differences.
    //   - ey row 0 is overwritten with fict[t].
    //   - hz interior points are updated using the *new* ex and ey.
    //   - hz boundary cells (last row/col) remain unchanged.
    //
    // The boundary Funcs are only used to make all neighbor
    // references well-defined; we still explicitly select old values
    // at the physical boundaries so the final result matches PolyBench.

    // Clamp hz so that hz_bc(x,y) is valid for all integer (x,y).
    Func hz_bc("hz_bc");
    hz_bc = Halide::BoundaryConditions::repeat_edge(hz_param);

    // ---- ex update ------------------------------------------------
    //
    // C code:
    //   for (i = 0; i < nx; i++)
    //     for (j = 1; j < ny; j++)
    //       ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    // plus implicit: ex[i][0] remains unchanged.
    //
    // Halide layout: ex(j, i) == ex[i][j]
    {
        Expr ex_old    = ex_param(j, i);
        Expr ex_update = ex_old - half * (hz_bc(j, i) - hz_bc(j - 1, i));

        // j == 0 -> keep old value, j > 0 -> updated value
        ex1(j, i) = select(j > 0, ex_update, ex_old);
    }

    // ---- ey update ------------------------------------------------
    //
    // C code:
    //   for (j = 0; j < ny; j++)
    //     ey[0][j] = _fict_[t];
    //   for (i = 1; i < nx; i++)
    //     for (j = 0; j < ny; j++)
    //       ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    // Halide layout: ey(j, i) == ey[i][j]
    {
        Expr ey_old    = ey_param(j, i);
        Expr ey_update = ey_old - half * (hz_bc(j, i) - hz_bc(j, i - 1));

        // i == 0 -> row set to fict[t]
        // i > 0  -> updated value
        ey1(j, i) = select(i == 0, fict_param, ey_update);
    }

    // Now that we have ex1 and ey1 for this time step, wrap them
    // with repeat_edge() so that neighbor accesses for hz1 near
    // the boundaries are also well-defined.
    Func ex_bc("ex_bc"), ey_bc("ey_bc");
    ex_bc = Halide::BoundaryConditions::repeat_edge(ex1);
    ey_bc = Halide::BoundaryConditions::repeat_edge(ey1);

    // ---- hz update ------------------------------------------------
    //
    // C code:
    //   for (i = 0; i < nx - 1; i++)
    //     for (j = 0; j < ny - 1; j++)
    //       hz[i][j] = hz[i][j]
    //                  - 0.7 * (ex[i][j+1] - ex[i][j]
    //                          + ey[i+1][j] - ey[i][j]);
    //
    // Note: hz is not updated for i == nx-1 or j == ny-1.
    //
    // Halide layout: hz(j, i) == hz[i][j]
    {
        // Domain extents as Expr so this works for arbitrary sizes.
        Expr ny_expr = hz_param.dim(0).extent();
        Expr nx_expr = hz_param.dim(1).extent();

        Expr interior = (j < ny_expr - 1) && (i < nx_expr - 1);

        Expr hz_old    = hz_param(j, i);
        Expr hz_update = hz_old -
                         seven_tenths *
                             ((ex_bc(j + 1, i) - ex_bc(j, i)) +
                              (ey_bc(j, i + 1) - ey_bc(j, i)));

        // Interior points get the updated value, boundary points keep
        // the original hz (matching the C loops which skip last row/col).
        hz1(j, i) = select(interior, hz_update, hz_old);
    }

    // ---------------- Scheduling -----------------------------------
    //
    // We now schedule the three output Funcs for efficient CPU
    // execution on a modern multi-core x86-64 machine:
    //   - Compute each at root (one full pass per field, like the C code).
    //   - Parallelize over the slow i-dimension (rows).
    //   - Vectorize over the contiguous j-dimension (columns).
    //
    // Boundary-condition Funcs (hz_bc, ex_bc, ey_bc) are left inlined;
    // their work is fused into the producer loops and benefits from
    // the same vectorization.

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    ex1.compute_root()
       .parallel(i)
       .vectorize(j, vec_width);

    ey1.compute_root()
       .parallel(i)
       .vectorize(j, vec_width);

    hz1.compute_root()
       .parallel(i)
       .vectorize(j, vec_width);

    // Build a Pipeline with three outputs: ex1, ey1, hz1.
    Pipeline fdtd_step({ex1, ey1, hz1});

    // JIT-compile once; we'll re-use it for every time-step.
    fdtd_step.compile_jit(target);

    // Double-buffering pointers for time-stepping.
    Halide::Buffer<num_t, 2> *ex_curr = &exA;
    Halide::Buffer<num_t, 2> *ey_curr = &eyA;
    Halide::Buffer<num_t, 2> *hz_curr = &hzA;

    Halide::Buffer<num_t, 2> *ex_next = &exB;
    Halide::Buffer<num_t, 2> *ey_next = &eyB;
    Halide::Buffer<num_t, 2> *hz_next = &hzB;

    // Start timing.
    auto start = std::chrono::high_resolution_clock::now();

    // Time-stepping loop (host-driven).
    for (int t = 0; t < tmax; t++) {
        // Bind current input fields.
        ex_param.set(*ex_curr);
        ey_param.set(*ey_curr);
        hz_param.set(*hz_curr);

        // Set current _fict_[t] value.
        fict_param.set(fict(t));

        // Realize next time-step into ex_next, ey_next, hz_next.
        Realization r({*ex_next, *ey_next, *hz_next});
        fdtd_step.realize(r);

        // Swap current and next buffers for the next iteration.
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    // Stop timing.
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Final fields are in *ex_curr, *ey_curr, *hz_curr.
    Halide::Buffer<num_t, 2> &ex_final = *ex_curr;
    Halide::Buffer<num_t, 2> &ey_final = *ey_curr;
    Halide::Buffer<num_t, 2> &hz_final = *hz_curr;

    // Optional: print the arrays to prevent dead-code elimination
    // (and to roughly match the original PolyBench behavior).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print ex
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << ex_final(j, i) << '\n';
            }
        }

        // Print ey
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << ey_final(j, i) << '\n';
            }
        }

        // Print hz
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << hz_final(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds (as in gemm.cpp example).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
