    ImageParam ex_param(type_of<num_t>(), 2, "ex_param");
    ImageParam ey_param(type_of<num_t>(), 2, "ey_param");
    ImageParam hz_param(type_of<num_t>(), 2, "hz_param");

    // Scalar parameter for _fict_[t] at the current time-step.
    Param<num_t> fict_param("fict_param");

    // Vars: j is the fast (x/column), i is the slow (y/row).
    Var j("j"), i("i");

    // Constants SCALAR_VAL(0.5) and SCALAR_VAL(0.7), in the correct numeric type.
    Expr half         = cast<num_t>(Expr(0.5));
    Expr seven_tenths = cast<num_t>(Expr(0.7));

    // Dimension extents as dynamic Exprs (taken from the input buffers at runtime).
    Expr ny_extent = ex_param.dim(0).extent();  // number of columns (C's ny)
    Expr nx_extent = ex_param.dim(1).extent();  // number of rows    (C's nx)

    // Bounded accessor for hz to safely handle (i-1) and (j-1) accesses.
    //
    // This implements a simple clamp-to-edge boundary condition, which ensures
    // Halide's bounds inference won't see any out-of-bounds accesses even though
    // the actual stencil only uses in-bounds values (our select() expressions
    // below prevent use of the clamped values on boundary points).
    Func hz_bc("hz_bc");
    {
        Var jb("jb"), ib("ib");
        Expr clamped_j = clamp(jb, 0, ny_extent - 1);
        Expr clamped_i = clamp(ib, 0, nx_extent - 1);
        hz_bc(jb, ib) = hz_param(clamped_j, clamped_i);
    }

    // New fields after a single time step (pure, pointwise definitions).
    //
    // We rewrite the original C loops as pure Halide expressions instead of
    // update definitions with RDom. This makes the dependence structure
    // explicit, which greatly simplifies scheduling (parallelization and
    // vectorization) while preserving the exact math of the original code.
    Func ey1("ey1"), ex1("ex1"), hz1("hz1");

    // ey update (from C):
    //
    // for (j = 0; j < ny; j++)
    //   ey[0][j] = _fict_[t];
    //
    // for (i = 1; i < nx; i++)
    //   for (j = 0; j < ny; j++)
    //     ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    // In Halide coordinates ey(j, i) == C ey[i][j]:
    //   if i == 0: ey1(j, i) = fict[t]
    //   else     : ey1(j, i) = ey(j, i) - 0.5 * (hz(j, i) - hz(j, i-1))
    //
    // We use hz_bc so that the (i-1) access is always in-bounds; the select()
    // guarantees that the boundary row i==0 is assigned fict[t], matching C.
    ey1(j, i) = select(i == 0,
                       fict_param,
                       ey_param(j, i) -
                           half * (hz_bc(j, i) - hz_bc(j, i - 1)));

    // ex update (from C):
    //
    // for (i = 0; i < nx; i++)
    //   for (j = 1; j < ny; j++)
    //     ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]);
