    //   if j == 0: ex1(j, i) = ex(j, i)
    //   else     : ex1(j, i) = ex(j, i) - 0.5 * (hz(j, i) - hz(j-1, i))
    //
    // Again we use hz_bc for the (j-1) access.
    ex1(j, i) = select(j == 0,
                       ex_param(j, i),
                       ex_param(j, i) -
                           half * (hz_bc(j, i) - hz_bc(j - 1, i)));

